function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}

const body = $json.body || {};

const jobId = String(body.jobId || body.job_id || '').trim();
const assetId = String(body.assetId || body.asset_id || '').trim();

const re = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!re.test(jobId) || !re.test(assetId)) {
  return {
    json: {
      ok: false,
      skipQuery: true,
      error: 'jobId and assetId are required UUIDs',
      jobId,
      assetId
    }
  };
}

const query = `
WITH asset AS (
  SELECT *
  FROM canonical_asset_registry
  WHERE asset_id = ${sql(assetId)}
  LIMIT 1
),
ins AS (
  INSERT INTO generated_assets (
    generated_asset_id,
    job_id,
    asset_id,
    avatar,
    scene,
    asset_type,
    status,
    review_notes,
    metadata,
    created_at,
    updated_at
  )
  SELECT
    gen_random_uuid(),
    ${sql(jobId)}::uuid,
    asset.asset_id::uuid,
    asset.avatar,
    asset.scene,
    asset.asset_type,
    'generated',
    NULL,
    jsonb_build_object(
      'source', 'generation-register',
      'jobId', ${sql(jobId)},
      'assetId', asset.asset_id,
      'bucket', asset.bucket,
      'objectPath', asset.object_path,
      'mimeType', asset.mime_type,
      'originalStatus', asset.status,
      'canonicalRegistryMetadata', asset.metadata
    ),
    now(),
    now()
  FROM asset
  ON CONFLICT (asset_id)
  DO UPDATE SET
    job_id = EXCLUDED.job_id,
    status = 'generated',
    review_notes = NULL,
    metadata = EXCLUDED.metadata,
    updated_at = now()
  RETURNING *
),
job_update AS (
  UPDATE generation_jobs
  SET status = 'review_required',
      completed_at = now(),
      updated_at = now()
  WHERE job_id = ${sql(jobId)}::uuid
    AND EXISTS (SELECT 1 FROM ins)
  RETURNING *
)
SELECT
  COALESCE((SELECT COUNT(*) FROM asset), 0) AS asset_found,
  COALESCE((SELECT row_to_json(ins) FROM ins LIMIT 1), NULL) AS generated_asset,
  COALESCE((SELECT row_to_json(job_update) FROM job_update LIMIT 1), NULL) AS job;
`;

return {
  json: {
    ok: true,
    skipQuery: false,
    query
  }
};
